import java.util.*;

public class Main {
    // same spreading step as HashMap.hash()
    static int spread(Object k) {
        int h = (k == null) ? 0 : k.hashCode();
        return h ^ (h >>> 16);
    }

    public static void main(String[] args) {
        int n = 16; // default table size
        Map<String, Integer> m = new HashMap<>();
        String[] keys = {"apple", "banana", "cherry", "apple"};
        for (String k : keys) {
            int h = spread(k);
            int idx = (n - 1) & h; // bucket index
            Integer old = m.put(k, k.length()); // returns previous value or null
            System.out.println(k + " hash=" + h + " bucket=" + idx + " put returned " + old);
        }
        System.out.println("size=" + m.size() + " map=" + m);
        // a null key always hashes to 0, so it lives in bucket 0
        System.out.println("null key bucket=" + ((n - 1) & spread(null)));
        System.out.println("putIfAbsent(apple) -> " + m.putIfAbsent("apple", 99));
        System.out.println("putIfAbsent(fig)   -> " + m.putIfAbsent("fig", 3));
    }
}

public class Main {
    public static void main(String[] args) {
        int n = 16;
        int[] hashes = {12345, -7, 0x10000, 0x20000};
        for (int h : hashes) {
            // for a power of two, AND with (n-1) is a cheap non-negative modulo
            System.out.println("h=" + h + "  h%n=" + (h % n)
                + "  floorMod=" + Math.floorMod(h, n) + "  h&(n-1)=" + (h & (n - 1)));
        }
        System.out.println("-- hashes that differ only in the high bits --");
        int a = 0x10000, b = 0x20000;
        System.out.println("no spread:   " + (a & (n - 1)) + " and " + (b & (n - 1)) + " (collide)");
        int sa = a ^ (a >>> 16), sb = b ^ (b >>> 16); // HashMap's spreading step
        System.out.println("with spread: " + (sa & (n - 1)) + " and " + (sb & (n - 1)));
        // doubling the table: a node stays at j or moves to j + oldCap
        int h = 0b10110; // 22
        int oldIdx = h & 15, newIdx = h & 31;
        System.out.println("old index " + oldIdx + ", new index " + newIdx
            + ", bit (h & oldCap) = " + (h & 16));
    }
}

import java.util.*;

public class Main {
    static int compares = 0; // counts compareTo calls

    // every key has the same hashCode, so all land in one bucket
    static class Key implements Comparable<Key> {
        final int id;
        Key(int id) { this.id = id; }
        @Override public int hashCode() { return 42; }
        @Override public boolean equals(Object o) { return o instanceof Key && ((Key) o).id == id; }
        @Override public int compareTo(Key o) { compares++; return Integer.compare(id, o.id); }
    }

    public static void main(String[] args) {
        // table of 128 >= MIN_TREEIFY_CAPACITY (64), so the long chain becomes a tree
        Map<Key, Integer> m = new HashMap<>(256);
        for (int i = 0; i < 40; i++) m.put(new Key(i), i);
        compares = 0;
        Integer v = m.get(new Key(39));
        System.out.println("size=" + m.size() + ", get(39)=" + v);
        // a plain chain would need up to 40 equals() calls and no compareTo at all
        System.out.println("compareTo calls during get: " + compares + " (tree walk, about log2(40))");
        System.out.println("tree path used: " + (compares > 0 && compares < 20));
    }
}

