public class Main {
    static void tryPut(String name, Map<String, Integer> m, String k, Integer v) {
        try {
            m.put(k, v);
            System.out.println(name + ": put(" + k + "," + v + ") ok");
        } catch (NullPointerException e) {
            System.out.println(name + ": put(" + k + "," + v + ") -> NullPointerException");
        }
    }

    public static void main(String[] args) {
        tryPut("HashMap", new HashMap<>(), null, 1);   // one null key allowed
        tryPut("HashMap", new HashMap<>(), "a", null); // null values allowed
        tryPut("Hashtable", new Hashtable<>(), null, 1);
        tryPut("ConcurrentHashMap", new ConcurrentHashMap<>(), "a", null);

        // synchronizedMap: single calls are safe, check-then-act is not
        Map<String, Integer> sm = Collections.synchronizedMap(new HashMap<>());
        synchronized (sm) { // hold the map's lock for the whole compound action
            if (!sm.containsKey("x")) sm.put("x", 1);
        }
        // ConcurrentHashMap gives atomic compound methods without external locks
        ConcurrentHashMap<String, Integer> chm = new ConcurrentHashMap<>();
        chm.merge("x", 1, Integer::sum);
        chm.merge("x", 1, Integer::sum);
        System.out.println("synchronizedMap=" + sm + " chm=" + chm);
    }
}

import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws InterruptedException {
        ConcurrentHashMap<String, Integer> counts = new ConcurrentHashMap<>();
        int threads = 4, perThread = 1000;
        Thread[] ts = new Thread[threads];
        for (int t = 0; t < threads; t++) {
            ts[t] = new Thread(() -> {
                for (int i = 0; i < perThread; i++) {
                    // merge is atomic per key: CAS on empty bin, lock on first node otherwise
                    counts.merge("hits", 1, Integer::sum);
                    counts.merge("key" + (i % 3), 1, Integer::sum);
                }
            });
            ts[t].start();
        }
        for (Thread t : ts) t.join();
        System.out.println("expected hits = " + (threads * perThread));
        System.out.println("hits = " + counts.get("hits"));
        System.out.println("key0 = " + counts.get("key0") + ", key1 = " + counts.get("key1")
            + ", key2 = " + counts.get("key2"));
        System.out.println("mappingCount = " + counts.mappingCount());
    }
}

