public class Main {
    public static void main(String[] args) {
        Map<String, String> hm = new HashMap<>();
        hm.put("k", null);
        // in HashMap, get alone is ambiguous; containsKey resolves it (single thread only)
        System.out.println("HashMap get(k)=" + hm.get("k") + " containsKey=" + hm.containsKey("k"));
        System.out.println("HashMap get(z)=" + hm.get("z") + " containsKey=" + hm.containsKey("z"));

        ConcurrentHashMap<String, String> chm = new ConcurrentHashMap<>();
        try {
            chm.put("k", null);
        } catch (NullPointerException e) {
            System.out.println("ConcurrentHashMap rejects null value");
        }
        // caching a "known missing" result with Optional instead of null
        ConcurrentHashMap<String, Optional<String>> cache = new ConcurrentHashMap<>();
        cache.put("user1", Optional.of("Ada"));
        cache.put("user2", Optional.empty()); // looked up, not found
        for (String id : new String[]{"user1", "user2", "user3"}) {
            Optional<String> v = cache.get(id);
            System.out.println(id + " -> " + (v == null ? "not cached" : v.isPresent() ? v.get() : "cached as missing"));
        }
    }
}

public class Main {
    public static void main(String[] args) {
        // simulate ArrayList's capacity growth: first add allocates 10, then old + old/2
        int cap = 0, size = 0;
        long copies = 0;
        StringBuilder caps = new StringBuilder();
        int n = 1000;
        for (int i = 1; i <= n; i++) {
            if (size == cap) {
                int newCap = (cap == 0) ? 10 : cap + (cap >> 1);
                copies += size; // Arrays.copyOf copies every existing element
                cap = newCap;
                if (caps.length() < 60) caps.append(cap).append(' ');
            }
            size++; // the add itself
        }
        System.out.println("adds = " + n);
        System.out.println("capacities: " + caps + "...");
        System.out.println("final capacity = " + cap);
        System.out.println("total element copies = " + copies);
        System.out.printf("copies per add = %.2f (stays constant, so add is amortized O(1))%n",
            (double) copies / n);
    }
}

import java.util.*;

public class Main {
    static long sumByIndex(List<Integer> list) {
        long s = 0;
        for (int i = 0; i < list.size(); i++) s += list.get(i); // LinkedList walks i nodes
        return s;
    }

    public static void main(String[] args) {
        int n = 20000;
        List<Integer> array = new ArrayList<>();
        List<Integer> linked = new LinkedList<>();
        for (int i = 0; i < n; i++) { array.add(i); linked.add(i); }

        long t0 = System.nanoTime();
        long s1 = sumByIndex(array);
        long t1 = System.nanoTime();
        long s2 = sumByIndex(linked);
        long t2 = System.nanoTime();
        System.out.println("n = " + n);
        System.out.println("ArrayList  get(i) loop: sum=" + s1 + " in " + (t1 - t0) / 1_000_000 + " ms (O(n) total)");
        System.out.println("LinkedList get(i) loop: sum=" + s2 + " in " + (t2 - t1) / 1_000_000 + " ms (O(n^2) total)");

        // LinkedList wins only when you already hold the position
        ListIterator<Integer> it = linked.listIterator(n / 2);
        it.add(-1); // O(1) insert at the iterator
        System.out.println("inserted via iterator, size=" + linked.size() + ", middle=" + linked.get(n / 2));
    }
}

import java.util.*;

public class Main {
    static class LRU<K, V> extends LinkedHashMap<K, V> {
        private final int capacity;
        LRU(int capacity) {
            super(capacity, 0.75f, true); // true = access order (get moves entry to the end)
            this.capacity = capacity;
        }
        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > capacity; // called after each insert; true evicts the head
        }
    }

    public static void main(String[] args) {
        LRU<String, Integer> cache = new LRU<>(3);
        cache.put("a", 1);
        cache.put("b", 2);
        cache.put("c", 3);
        System.out.println("start:        " + cache);
        cache.get("a"); // a becomes most recently used
        System.out.println("after get(a): " + cache);
        cache.put("d", 4); // evicts the least recently used key (b)
        System.out.println("after put(d): " + cache);
        System.out.println("contains b? " + cache.containsKey("b"));
        // all operations are O(1); every get also mutates the list, so it is not thread-safe
    }
}

