public class Main {
    public static void main(String[] args) {
        TreeMap<Integer, String> t = new TreeMap<>();
        for (int k : new int[]{50, 20, 80, 10, 30, 70, 90}) t.put(k, "v" + k);
        System.out.println("sorted keys: " + t.keySet());
        // navigation methods are O(log n) because the tree is balanced
        System.out.println("floor(55)=" + t.floorKey(55) + " ceiling(55)=" + t.ceilingKey(55)
            + " lower(50)=" + t.lowerKey(50) + " higher(50)=" + t.higherKey(50));
        System.out.println("subMap[20,80) = " + t.subMap(20, 80));

        // TreeMap uses the comparator, never equals(), to detect duplicates
        TreeMap<String, Integer> ci = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
        ci.put("Apple", 1);
        ci.put("APPLE", 2); // same key by the comparator, so it replaces the value
        System.out.println("case-insensitive map: " + ci + " size=" + ci.size());

        try {
            t.put(null, "x"); // natural ordering cannot compare null
        } catch (NullPointerException e) {
            System.out.println("put(null) -> NullPointerException");
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> data = Arrays.asList(5, 3, 8, 1, 9, 2);
        System.out.println("input:                 " + data);

        // constructor from a collection uses Floyd's heapify: O(n)
        PriorityQueue<Integer> pq = new PriorityQueue<>(data);
        System.out.println("heap array order:      " + pq); // not sorted
        System.out.println("peek (smallest, O(1)): " + pq.peek());

        // children of index i are 2i+1 and 2i+2; parent is (i-1)/2
        Integer[] arr = pq.toArray(new Integer[0]);
        for (int i = 0; i < arr.length; i++) {
            int l = 2 * i + 1, r = 2 * i + 2;
            if (l < arr.length && arr[l] < arr[i]) System.out.println("heap violated at " + i);
            if (r < arr.length && arr[r] < arr[i]) System.out.println("heap violated at " + i);
        }
        System.out.println("heap property holds for all parents");

        StringBuilder out = new StringBuilder();
        while (!pq.isEmpty()) out.append(pq.poll()).append(' '); // each poll is O(log n)
        System.out.println("poll order:            " + out.toString().trim());
    }
}

import java.util.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) {
        // 1) fail-fast: structural change during iteration throws
        List<Integer> list = new ArrayList<>(List.of(1, 2, 3, 4));
        try {
            for (Integer x : list) if (x == 2) list.remove(x);
        } catch (ConcurrentModificationException e) {
            System.out.println("ArrayList: ConcurrentModificationException");
        }
        // safe ways to remove while iterating
        list.removeIf(x -> x % 2 == 0);
        System.out.println("after removeIf: " + list);

        // 2) weakly consistent: never throws
        ConcurrentHashMap<String, Integer> chm = new ConcurrentHashMap<>();
        chm.put("a", 1); chm.put("b", 2);
        for (String k : chm.keySet()) chm.put("c", 3); // allowed
        System.out.println("CHM after loop: " + new TreeMap<>(chm));

        // 3) snapshot: iterator keeps the array it started with
        CopyOnWriteArrayList<Integer> cow = new CopyOnWriteArrayList<>(List.of(1, 2, 3));
        for (Integer x : cow) { if (x == 1) cow.add(99); System.out.print("saw " + x + " "); }
        System.out.println("-> list now " + cow);
    }
}

import java.util.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) {
        CopyOnWriteArrayList<String> listeners = new CopyOnWriteArrayList<>();
        listeners.add("logger");
        listeners.add("metrics");

        // iteration sees the array as it was when the iterator was created
        Iterator<String> it = listeners.iterator();
        listeners.add("audit"); // writes copy the whole array
        System.out.print("snapshot sees:");
        while (it.hasNext()) System.out.print(" " + it.next());
        System.out.println();
        System.out.println("list now: " + listeners);

        try {
            Iterator<String> it2 = listeners.iterator();
            it2.next();
            it2.remove(); // snapshot iterators do not support remove
        } catch (UnsupportedOperationException e) {
            System.out.println("iterator.remove -> UnsupportedOperationException");
        }

        System.out.println("addIfAbsent(logger) = " + listeners.addIfAbsent("logger"));
        System.out.println("addIfAbsent(trace)  = " + listeners.addIfAbsent("trace"));

        // cost of a write grows with size: every add copies the array
        CopyOnWriteArrayList<Integer> big = new CopyOnWriteArrayList<>();
        long t0 = System.nanoTime();
        for (int i = 0; i < 20000; i++) big.add(i); // O(n^2) total
        System.out.println("20000 adds took " + (System.nanoTime() - t0) / 1_000_000 + " ms");
    }
}

import java.util.*;

public class Main {
    static class Point {
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
        @Override public int hashCode() { return Objects.hash(x, y); }
        @Override public boolean equals(Object o) {
            return o instanceof Point && ((Point) o).x == x && ((Point) o).y == y;
        }
        @Override public String toString() { return "(" + x + "," + y + ")"; }
    }

    public static void main(String[] args) {
        Map<Point, String> map = new HashMap<>();
        Point p = new Point(1, 2);
        map.put(p, "home");
        System.out.println("before mutation: get=" + map.get(p) + " size=" + map.size());

        p.x = 99; // mutate a field used by hashCode/equals while it is a key

        System.out.println("after mutation:  get(p)=" + map.get(p));
        System.out.println("containsKey(p)=" + map.containsKey(p));
        System.out.println("remove(p)=" + map.remove(p));
        System.out.println("new Point(1,2) lookup=" + map.get(new Point(1, 2)));
        System.out.println("size still " + map.size() + ", iteration shows " + map);
        // the entry is stuck in the old bucket: it can only be seen by iterating
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        // three keys A, B, C sit in one bucket; resize sends them to the same new bucket
        List<String> chain = List.of("A", "B", "C");
        System.out.println("old chain:      " + chain);

        // Java 7 transfer(): each node is inserted at the HEAD of the new bucket
        LinkedList<String> java7 = new LinkedList<>();
        for (String n : chain) java7.addFirst(n);
        System.out.println("Java 7 result:  " + java7 + "  (reversed)");

        // Java 8 resize(): lo/hi lists are built with a tail pointer, so order is preserved
        LinkedList<String> java8 = new LinkedList<>();
        for (String n : chain) java8.addLast(n);
        System.out.println("Java 8 result:  " + java8 + "  (order kept)");

        // why reversing is dangerous: two threads each reverse the same chain.
        // thread 1 saved e=A, next=B; thread 2 finishes and the chain is C -> B -> A.
        // thread 1 resumes: A.next = B, and B.next is already A  => cycle A <-> B
        Map<String, String> next = new HashMap<>();
        next.put("C", "B"); next.put("B", "A"); // chain after thread 2 reversed it
        next.put("A", "B");                      // thread 1 links A.next = B
        String cur = "A"; int steps = 0;
        while (cur != null && steps < 6) { System.out.print(cur + " -> "); cur = next.get(cur); steps++; }
        System.out.println("... never reaches null (infinite loop in get)");
    }
}

public class Main {
    // tiny open-addressing map from long to long (keys must be > 0; 0 means empty)
    static long[] keys = new long[2048], vals = new long[2048];

    static void put(long k, long v) {
        int i = (int) ((k * 0x9E3779B97F4A7C15L) >>> 53); // 11 bits -> 0..2047
        while (keys[i] != 0 && keys[i] != k) i = (i + 1) & 2047; // linear probing
        keys[i] = k; vals[i] = v;
    }

    static long get(long k) {
        int i = (int) ((k * 0x9E3779B97F4A7C15L) >>> 53);
        while (keys[i] != 0) { if (keys[i] == k) return vals[i]; i = (i + 1) & 2047; }
        return -1;
    }

    public static void main(String[] args) {
        long entries = 10_000_000L;
        long node = 32, boxedKey = 16, boxedVal = 16;
        double tableSlot = 4 / 0.75; // 4-byte reference, load factor <= 0.75
        double hashMapBytes = entries * (node + boxedKey + boxedVal + tableSlot);
        double primitiveBytes = entries * 16 / 0.5; // two long arrays at load factor 0.5
        System.out.printf("HashMap<Long,Long>: about %.0f MB%n", hashMapBytes / 1e6);
        System.out.printf("long[] open addressing: about %.0f MB%n", primitiveBytes / 1e6);
        System.out.printf("raw data: %.0f MB%n", entries * 16 / 1e6);

        for (long k = 1; k <= 1000; k++) put(k, k * k);
        System.out.println("get(7)=" + get(7) + " get(1000)=" + get(1000) + " get(5000)=" + get(5000));
    }
}
